from core import *

def papers():
 p=[]
 p.append(item('Calculate 14.4 ÷ 1.2 + 3.5.','15.5','Divide first: 14.4÷1.2=144÷12=12. Then add 3.5 to obtain 15.5.','DIG-01',['12.5','14.7','16.5','17.9']))
 p.append(item('Thirty students stand in a line. Zoe is 8th from the front and Kai is 9th from the back. They swap positions. What is Zoe’s new position from the front?',22,'Kai’s position from the front is 30−9+1=22. Zoe takes that position in the swap, so she becomes 22nd.','COUNT-01',[20,21,23,24],check=30-9+1))
 p.append(item('A tank receives 2.4 litres per minute for 35 minutes. The water is poured into bottles holding 700 mL each. How many bottles are filled?',120,'The tank receives 2.4×35=84 litres=84000 mL. Each bottle holds 700 mL, so 84000÷700=120 bottles are filled.','RATE-01',[84,100,112,140],check=84000//700))
 p.append(item('Of 75 students, 48 take art and 42 take music. Exactly 24 take both. How many take neither?',9,'The union is 48+42−24=66. Subtract from all 75 students to find 9 who take neither.','COUNT-04',[6,12,15,18],check=75-48-42+24))
 p.append(item('A pattern starts with 5 dots. Every next stage doubles the current number and then adds 1. How many dots are in the fourth stage?',47,'Apply both operations at each step: 5→11→23→47. The starting collection is stage one, so only three changes are made.','SEQ-04',[41,45,46,95],check=((5*2+1)*2+1)*2+1))
 p.append(item('A red block and a blue block together weigh 19 g. Two red blocks and three blue blocks weigh 48 g. What does a red block weigh?',9,'Twice the first collection is two red and two blue, weighing 38 g. The extra blue block weighs 48−38=10 g. A red block therefore weighs 19−10=9 g.','ALG-03',[8,10,11,12],check=19-(48-2*19)))
 p.append(item('Four different children stand in a row. Ana and Ben must not stand next to one another. How many orders are possible?',12,'There are 4!=24 total orders. If Ana and Ben are together, their block and the other two children have 3!=6 orders, with 2 orders inside the block: 12. Subtract those from 24 to leave 12.','COUNT-04',[6,8,16,18],check=math.factorial(4)-2*math.factorial(3)))
 p.append(item('What is the units digit of 7⁴⁵ − 3⁴⁴?',6,'Powers of 7 have cycle 7,9,3,1, so exponent 45 selects 7. Powers of 3 have cycle 3,9,7,1, so exponent 44 selects 1. The difference ends in 7−1=6.','DIV-05',[2,4,7,8],check=(pow(7,45,10)-pow(3,44,10))%10))
 p.append(item('Four identical workers paint six rooms in nine hours. At that rate, how many hours do six workers take to paint eight rooms?',8,'The first job uses 4×9=36 worker-hours for six rooms, or 6 worker-hours per room. Eight rooms need 48 worker-hours. Six workers take 48÷6=8 hours.','RATE-02',[6,7,10,12],check=4*9//6*8//6))
 p.append(item('A date is four days after the day that is two weeks before the day that is nine days after Saturday 20 February. What date is it?','Friday 19 February','The net movement is +9−14+4=−1 day. One day before Saturday 20 February is Friday 19 February. The month boundary is never needed for the final calculation.','ALG-04',['Thursday 18 February','Saturday 20 February','Sunday 21 February','Monday 22 February']))
 p.append(item('Two gears begin with marked teeth together. One has 18 teeth and the other 24. After how many tooth-to-tooth contacts do both marked teeth first meet again?',72,'Both marked teeth meet after a number of contacts divisible by 18 and 24. Their least common multiple is 72. That is four complete turns of the first gear and three of the second.','DIV-02',[36,48,96,432],check=math.lcm(18,24)))
 p.append(item('A courier charges $15 for the first 4 kg, plus $3 for each extra 2 kg or part thereof. A parcel costs $30 to send. Which listed mass could it have?', '13 kg','The extra $15 pays for five 2 kg blocks. That means the extra mass is more than 8 kg but no more than 10 kg, so total mass is more than 12 kg and at most 14 kg. Only 13 kg fits.','RATE-01',['10 kg','11 kg','12 kg','15 kg']))
 p.append(item('An equilateral triangle and a regular hexagon have the same side length. Their perimeters differ by 27 cm. What is their combined perimeter?', '81 cm','The difference is three side lengths, so each side is 27÷3=9 cm. Together they have nine sides, giving 9×9=81 cm of perimeter.','GEO-01',['54 cm','63 cm','72 cm','108 cm']))
 p.append(item('A machine follows the rule multiply by a fixed number, then add a fixed number. Input 3 produces 20, and input 11 produces 52. What input produces 100?',23,'An input increase of 8 produces an output increase of 32, so the multiplier is 4. The rule is 4x+8. Solve 4x+8=100: x=23.','ALG-03',[21,22,24,25],check=(100-8)//4))
 p.append(item('A group of 12 students has a mean score of 15. Three students leave the group, and the remaining mean is 16. What was the mean score of the three who left?',12,'The original total is 180. The remaining nine total 144, so the three departing students total 36. Their mean is 36÷3=12.','DATA-02',[9,10,11,13],check=(12*15-9*16)//3))
 p.append(item('A 16 cm by 10 cm rectangle has a smaller rectangle removed from one corner. The removed rectangle is 6 cm by 4 cm. What is the perimeter of the remaining L shape?', '52 cm','The original perimeter is 2(16+10)=52 cm. The corner cut removes outer edges of 6 and 4 cm but exposes new edges of the same two lengths. The perimeter is unchanged, 52 cm.','GEO-01',['32 cm','42 cm','62 cm','72 cm'],figure=polygon([(70,30),(270,30),(270,110),(390,110),(390,230),(70,230)],[(170,22,'10 cm'),(365,95,'6 cm'),(300,68,'4 cm'),(230,250,'16 cm')])) )
 p.append(item('A number has six digits, all 3. What is the digit sum of three times that number plus 1?',1,'Three times 333333 is 999999. Adding 1 produces 1000000, whose digit sum is 1. The carry passes through all six 9s.','DIG-04',[6,9,18,54],check=sum(map(int,str(333333*3+1)))))
 p.append(item('Exactly two statements are true about a number N: “N is divisible by 2”; “N is divisible by 3”; “N is divisible by 5”. Which listed number could N be?',18,'For 18, divisibility by 2 and 3 is true, while divisibility by 5 is false: exactly two. For 30 all three are true; 7 satisfies none; 8 and 25 satisfy only one each.','LOGIC-01',[30,7,8,25]))
 p.append(item('A group has twice as many adults as children. Three quarters of the adults and half the children wear hats, totalling 84 hat-wearers. How many people are in the group?',126,'Let the child count be c and adult count 2c. Hat-wearers number (3/4)(2c)+(1/2)c=2c=84, so c=42. The group has 3c=126 people.','FRAC-04',check=84//2*3))
 p.append(item('A light flashes at minutes 1, 5, 9, …, repeating every 4 minutes. Another flashes at minutes 5, 11, 17, …, repeating every 6 minutes. What is the first common flash strictly after minute 20?',29,'They first meet at minute 5. Common flashes then repeat every lcm(4,6)=12 minutes: 5,17,29,… . The first one strictly after 20 is 29. The initial offset must be kept as well as the common interval.','DIV-02',check=next(n for n in range(21,100) if (n-1)%4==0 and (n-5)%6==0)))
 p.append(item('A, B and C are different nonzero digits. The three-digit number ABC is four times the two-digit number CB. What is ABC?',328,'The equation is 100A+10B+C=4(10C+B), or 100A+6B=39C. The right side and 6B are divisible by 3, so A is 3,6 or 9. But four times a two-digit number is below 400, forcing A=3. Then 100+2B=13C. The only possible digit C is 8, giving 100+2B=104 and B=2. Check 328=4×82.','DIG-05',check=next(100*a+10*b+c for a,b,c in permutations(range(1,10),3) if 100*a+10*b+c==4*(10*c+b))))
 p.append(item('A block is 6 cubes wide, 5 deep and 4 high. Its top and bottom are blue; its four vertical faces are red. It is cut into unit cubes. How many cubes have exactly one blue face and exactly one red face?',28,'Such cubes lie on the perimeter of the top or bottom layer but are not corners, since corners have two red faces. Each layer contributes 2(6−2)+2(5−2)=14. The separate top and bottom layers give 28.','SOLID-02',check=2*(2*(6-2)+2*(5-2)),figure=cuboid(6,5,4).replace('#c4e5df','#87b9ed').replace('#91c7c2','#e59591').replace('#5f9faa','#cf7275')))
 p.append(item('A shop sells three sevenths of its notebooks in the morning, then five eighths of the remainder in the afternoon. Forty-two notebooks remain. How many were there initially?',196,'The retained fraction is (4/7)(3/8)=3/14. If 3/14 is 42, then 1/14 is 14 and the full stock is 196. Check: 196→112→42.','FRAC-01',check=int(F(42)/(F(4,7)*F(3,8)))))
 one=paper('rossmoyne',7,p)
 p=[]
 p.append(item('Calculate 3.75 × 12 − 5.',40,'Twelve lots of 3.75 are 45, since four lots make 15. Subtracting 5 gives 40.','DIG-01',[35,37.5,42.5,45],check=3.75*12-5))
 p.append(item('Ava is 14th from the front of a queue. Seven people in front of her leave and five people join at the back. What is Ava’s new position from the front?',7,'Only departures in front change her front position. Subtract the seven who leave: 14−7=7. People joining behind her do not affect her rank from the front.','COUNT-01',[6,8,12,19],check=14-7))
 p.append(item('A runner completes 2.7 km in 15 minutes. At that rate, how many metres does the runner cover in 4 minutes?',720,'Convert 2.7 km to 2700 m. The rate is 2700÷15=180 m per minute. Four minutes cover 180×4=720 m.','RATE-03',[540,680,750,1080],check=2700//15*4))
 p.append(item('A group of 100 people includes 62 tea drinkers and 51 coffee drinkers. Thirty-five drink both. How many drink exactly one of the two?',43,'Tea only is 62−35=27 and coffee only is 51−35=16. Add these disjoint groups to obtain 43. The 22 who drink neither are not counted.','COUNT-04',[22,35,48,78],check=62+51-2*35))
 p.append(item('A growing pattern has 2, 6, 12, 20, 30, … tiles. The nth design has n rows and n+1 columns. How many tiles are in design 12?',156,'Use the stated construction: design 12 has 12 rows of 13 tiles. The total is 12×13=156. This rule, not just a guessed continuation, determines the answer.','SEQ-01',[132,144,169,182],check=12*13))
 p.append(item('Three red counters and two blue counters are worth 31 points. One red and two blue are worth 17. How many points is one blue counter worth?',5,'Subtracting the second collection from the first gives two red counters worth 14, so red is 7. Then two blue are worth 17−7=10, making each blue worth 5.','ALG-03',[4,6,7,10],check=(17-(31-17)//2)//2))
 p.append(item('Five different people sit in five numbered seats. Two specified people must occupy the two end seats. How many arrangements are possible?',12,'The two specified people can swap ends in 2 ways. The three others fill the middle seats in 3!=6 ways. Thus 2×6=12 arrangements.','COUNT-02',[6,18,24,48],check=2*math.factorial(3)))
 p.append(item('What is the remainder when 2⁵⁰ is divided by 7?',4,'Powers of 2 modulo 7 repeat 2,4,1. Since 50 leaves remainder 2 when divided by 3, choose the second remainder, 4.','DIV-05',[0,1,2,6],check=pow(2,50,7)))
 p.append(item('A pipe fills a tank in 15 minutes. With a drain also open, the tank fills in 25 minutes. How many minutes does the drain alone take to empty a full tank?',37.5,'The drain rate is the pipe rate minus the net filling rate: 1/15−1/25=2/75 tank per minute. Emptying one tank takes 75/2=37.5 minutes.','RATE-02',[10,30,40,60],check=float(1/(F(1,15)-F(1,25)))))
 p.append(item('Starting from Tuesday 7 July, move forward 30 days, back two weeks, and forward 5 days. What is the final weekday?','Tuesday','The net shift is 30−14+5=21 days, exactly three weeks. Whole weeks leave the weekday unchanged, so it is Tuesday.','DIV-05',['Monday','Wednesday','Friday','Sunday']))
 p.append(item('Three bells ring every 12, 15 and 20 minutes. They ring together at 1 pm. How many times do all three ring together strictly after 1 pm and no later than 5 pm?',4,'The common interval is lcm(12,15,20)=60 minutes. In the next four hours they ring together at 2,3,4,5 pm, giving four events.','DIV-02',[3,5,8,12],check=240//math.lcm(12,15,20)))
 p.append(item('A storage fee is $20 for the first week, then $8 for each additional week or part of a week. What is charged for 24 days?','$44','The included week covers 7 days. The remaining 17 days require three additional week blocks. The total is 20+3×8=$44.','RATE-01',['$36','$40','$48','$52']))
 p.append(item('An isosceles triangle has an exterior angle of 130° at its apex, between an extended equal side and the other equal side. What is either base angle?', '65°','The interior apex angle is 180−130=50°. The equal base angles share 180−50=130°, so each is 65°.','GEO-03',['25°','50°','60°','75°']))
 p.append(item('A rule has the form output = a×input+b. Input 2 gives 19 and input 8 gives 43. What is a+b?',15,'The output change is 24 over input change 6, giving a=4. Then 2×4+b=19 means b=11. Thus a+b=15.','ALG-03',[11,13,17,19],check=4+11))
 p.append(item('Six children have mean age 11. A seventh joins, raising the mean to 12. How old is the seventh child?',18,'The first six ages total 66. The seven ages total 84. The added age is 84−66=18.','DATA-02',[12,13,16,17],check=7*12-6*11))
 p.append(item('A right triangle has perpendicular sides 9 cm and 12 cm. A smaller right triangle with perpendicular sides 3 cm and 4 cm is removed from it. What is the remaining area?', '48 cm²','The large area is 9×12÷2=54 cm², and the small area is 3×4÷2=6 cm². Subtract to leave 48 cm².','GEO-02',['42 cm²','45 cm²','51 cm²','96 cm²']))
 p.append(item('A wire is bent into a rectangle whose length is three times its width. The same wire can make a square of side 18 cm. What is the rectangle’s area?', '243 cm²','The wire length is 4×18=72 cm. If the rectangle’s width is w, perimeter=2(w+3w)=8w, so w=9 and length=27. Its area is 9×27=243 cm².','GEO-05',['162 cm²','216 cm²','288 cm²','324 cm²']))
 p.append(item('What is the sum of the digits of 10¹⁸ − 10⁹?',81,'The number is nine 9s followed by nine zeros: 999999999000000000. Its digit sum is 9×9=81. The nine zeros come from the factor 10⁹.','DIG-04',[72,80,90,162],check=sum(map(int,str(10**18-10**9)))))
 p.append(item('A bus has 48 passengers. Three eighths are adults and the rest children. At the next stop, 6 adults and 12 children leave. What percentage of the remaining passengers are adults?',40,'Initially there are 18 adults and 30 children. Afterwards there are 12 adults and 18 children, 30 people altogether. Adults make up 12/30=40%.','FRAC-04',check=12*100//30))
 p.append(item('Two lights flash together now, then at intervals of 28 and 42 seconds. How many flashes does the faster light make strictly before the next simultaneous flash, excluding the flash now?',2,'They next meet after lcm(28,42)=84 seconds. The faster light flashes before then at 28 and 56 seconds only. The 84-second flash is simultaneous and excluded.','DIV-02',check=math.lcm(28,42)//28-1))
 p.append(item('A, B and C are different nonzero digits. The three-digit number ABC is eight times the two-digit number CB. What is ABC?',384,'Use place value: 100A+10B+C=8(10C+B), giving 100A=79C−2B. Since the right side is even, C is even. Test C=2,4,6,8, with B from 1 to 9. For C=2 the right side is 140–156; C=4 gives 298–314 and only 300 is possible, with B=8; C=6 gives 456–472; C=8 gives 614–630. Only C=4,B=8,A=3 works. Check 384=8×48.','DIG-05',check=next(100*a+10*b+c for a,b,c in permutations(range(1,10),3) if 100*a+10*b+c==8*(10*c+b))))
 p.append(item('A 5-by-5-by-5 cube is painted on its top and four vertical faces, but not its bottom. It is cut into unit cubes. How many unit cubes have paint on exactly two faces?',28,'Top-edge cubes excluding the four top corners have one top and one side face painted: 4×(5−2)=12. The four vertical edges each contribute four cubes below their top corner; these have two side faces painted, including their bottom cube. That gives 4×4=16. Total 12+16=28. Top corners have three painted faces and are excluded.','SOLID-02',check=4*(5-2)+4*(5-1),figure=cuboid(5,5,5)))
 p.append(item('A shop sells one sixth of its apples, then half of the remainder. After buying 25 more apples, it has 100. How many did it have initially?',180,'Before restocking, 100−25=75 apples remained. The retained fraction was (5/6)(1/2)=5/12. Therefore the original stock was 75×12÷5=180. Check 180→150→75→100.','FRAC-01',check=int(F(100-25)/(F(5,6)*F(1,2)))))
 two=paper('rossmoyne',8,p)
 p=[]
 p.append(item('Calculate 0.48 × 250.',120,'Since 250 is 1000÷4, compute 0.48×1000÷4=480÷4=120.','DIG-01',[12,24,96,125],check=.48*250))
 p.append(item('In a line of 52 students, Lani is 17th from the front and Max is 18th from the back. How many students are strictly between them?',17,'Max is 52−18+1=35th from the front. The positions strictly between 17 and 35 number 35−17−1=17.','COUNT-01',[16,18,19,20],check=52-18+1-17-1))
 p.append(item('A bus travels 156 km in 2 hours 10 minutes at constant speed. How many kilometres does it travel in 25 minutes?',30,'The full journey lasts 130 minutes, so the speed is 156÷130=1.2 km per minute. In 25 minutes the distance is 1.2×25=30 km.','RATE-03',[25,26,32,36],check=156/130*25))
 p.append(item('A group has 84 people. Fifty use a train, 45 use a bus, and 23 use both at some point. How many use neither?',12,'The union is 50+45−23=72 people. Subtracting from 84 gives 12 who use neither.','COUNT-04',[11,13,22,23],check=84-50-45+23))
 p.append(item('A square has side length 3 cm. Each new square has a side 2 cm longer than the previous square. What is the perimeter of the eighth square?', '68 cm','The eighth square follows seven increases, so its side is 3+7×2=17 cm. Its perimeter is 4×17=68 cm.','SEQ-01',['60 cm','64 cm','72 cm','76 cm']))
 p.append(item('Four identical mugs and a plate cost $33. Two mugs and the same plate cost $21. What does the plate cost?','$9','Subtract the two collections to find that two mugs cost $12, so each mug is $6. Then the plate costs 21−2×6=$9.','ALG-03',['$6','$7','$12','$15']))
 p.append(item('A three-digit number uses three different digits chosen from 1, 2, 3, 4 and 5. Its units digit must be even and its hundreds digit must be odd. How many such numbers are possible?',18,'Choose the units digit from 2 or 4: two ways. Choose the hundreds digit from 1,3,5: three ways. The tens digit then has three remaining choices. Total 2×3×3=18.','DIG-02',[12,15,24,30],check=sum(a%2==1 and c%2==0 for a,b,c in permutations(range(1,6),3))))
 p.append(item('What is the last digit of 3⁶¹ + 7⁶²?',2,'Powers of 3 have period 4 and exponent 61 selects last digit 3. Powers of 7 also have period 4 and exponent 62 selects 9. Their sum ends like 12, so the units digit is 2.','DIV-05',[0,3,6,8],check=(pow(3,61,10)+pow(7,62,10))%10))
 p.append(item('One tap fills a tank in 20 minutes and another in 30 minutes. They operate together for 6 minutes. What fraction of the tank is still empty?','1/2','The combined rate is 1/20+1/30=1/12 tank per minute. Six minutes fills 6/12=1/2, so the other half remains empty.','RATE-02',['1/3','2/5','3/5','2/3'],check=str(1-6*(F(1,20)+F(1,30)))))
 p.append(item('Starting at 2:15 pm, a clock advances 809 hours and then 50 minutes. What time does it show?','8:05 am','Since 809 leaves remainder 17 modulo 24, the hours take 2:15 pm to 7:15 am. Adding 50 minutes gives 8:05 am.','DIV-05',['7:05 am','7:45 am','8:05 pm','9:05 am']))
 p.append(item('Three rotating wheels complete a revolution in 9, 12 and 20 seconds. After starting with their marks aligned, how many revolutions does the fastest wheel make before all marks next align?',20,'The next common alignment is after lcm(9,12,20)=180 seconds. The fastest wheel takes 9 seconds per turn, so it makes 180÷9=20 revolutions.','DIV-02',[9,15,18,30],check=math.lcm(9,12,20)//9))
 p.append(item('A service charges $25 for the first 12 kg and $7 for every additional 4 kg or part thereof. A parcel costs $53. Which listed mass could the parcel have?', '27 kg','The extra $28 pays for four blocks. The extra mass is therefore more than 12 kg and no more than 16 kg, so the total is more than 24 kg and at most 28 kg. Only 27 kg fits.','RATE-01',['20 kg','24 kg','29 kg','32 kg']))
 p.append(item('The two equal sides of an isosceles triangle are each 5 cm longer than its base. Its perimeter is 46 cm. What is its base length?', '12 cm','If the base is b, the total is b+(b+5)+(b+5)=3b+10=46. Thus 3b=36 and b=12 cm. The other sides are 17 cm.','GEO-01',['10 cm','13 cm','15 cm','17 cm']))
 p.append(item('A machine multiplies its input by a positive whole number, then subtracts a fixed number. Input 6 gives 29 and input 13 gives 71. What does input 20 give?',113,'The multiplier is (71−29)/(13−6)=42/7=6. The subtracted amount is 6×6−29=7. Input 20 gives 120−7=113.','ALG-03',[107,111,115,120],check=6*20-7))
 p.append(item('Four classes raise $610. The largest amount is $20 more than the second, $35 more than the third and $55 more than the fourth. What is the largest amount?','$180','Let the largest be w. The total is 4w−20−35−55=610, so 4w=720 and w=180. The other amounts are 160,145,125, checking the total.','ALG-05',['$160','$170','$175','$190']))
 p.append(item('A rectangular garden is 18 m by 12 m. A path of uniform width 2 m runs inside its boundary. What is the area of the path?', '104 m²','The whole area is 18×12=216 m². The unpaved centre measures 14 m by 8 m, with area 112 m². The path is the difference, 216−112=104 m².','GEO-02',['96 m²','100 m²','112 m²','120 m²'],figure=grid(9,6,[(x,y) for x in range(9) for y in range(6) if x in [0,8] or y in [0,5]])))
 p.append(item('A wire of length 96 cm is bent into a rectangle. Its width is one third of its length. What is the difference between its two dimensions?', '24 cm','If the width is w, length is 3w and perimeter is 8w=96, so w=12 and length=36. The difference is 24 cm.','GEO-05',['12 cm','18 cm','30 cm','36 cm']))
 p.append(item('What is the sum of the digits of 111111111 × 9 + 2?',2,'Nine times nine 1s gives nine 9s, 999999999. Adding 2 gives 1000000001. Its digit sum is 1+1=2.','DIG-04',[1,9,18,81],check=sum(map(int,str(111111111*9+2)))))
 p.append(item('A group consists of 32 families, each with two adults. Half have one child, one quarter have three children and the rest have four children. How many people are in the group?',136,'There are 64 adults. The child counts are 16×1+8×3+8×4=72. The total is 64+72=136.','FRAC-04',check=32*2+16+8*3+8*4))
 p.append(item('Three boards have lengths 180 cm, 252 cm and 324 cm. Each is cut into pieces of the same greatest possible whole-number length without waste. How many cuts are made in total?',18,'The greatest common divisor is 36 cm. The boards become 5,7,9 pieces. A straight board needs one fewer cut than pieces, so the total cuts are 4+6+8=18. Do not count the original three starting pieces as cuts.','DIV-02',check=(180+252+324)//math.gcd(180,math.gcd(252,324))-3))
 p.append(item('A, B and C are different nonzero digits. The three-digit number ABC is five times the two-digit number CB. What is ABC?',295,'The units digit of five times a nonzero integer is 0 or 5. Since C is nonzero, C=5 and B must be odd. The equation becomes 100A+10B+5=5(50+B), so 20A+B=49. With B a digit and A nonzero, the only possibility is A=2,B=9. Check 295=5×59.','DIG-05',check=next(100*a+10*b+c for a,b,c in permutations(range(1,10),3) if 100*a+10*b+c==5*(10*c+b))))
 p.append(item('A 5-by-5-by-5 cube of unit cubes has its central vertical column of five cubes removed, leaving a square tunnel from top to bottom. All exposed faces, including the tunnel walls, are then painted. How many remaining unit cubes have no paint?',12,'Unpainted cubes cannot be in the top or bottom layer, leaving three middle layers. In each layer, consider the inner 3×3 region: its central square is the tunnel, and its four side-neighbours touch the painted tunnel wall. Only the four corner squares of that inner region remain unpainted. Thus there are 3×4=12 cubes.','SOLID-02',check=3*4,figure=grid(5,5,[(2,2)],labels={(2,2):'hole'})))
 p.append(item('A collection loses one quarter of its objects. Then 21 objects are added. Finally one third of the new collection is removed, leaving 70. How many objects were in the original collection?',112,'Undo the last removal: before it there were 70×3/2=105 objects. Undo the addition: 105−21=84. This is three quarters of the initial collection, so the initial count is 84×4/3=112. Check 112→84→105→70.','FRAC-01',check=(70*3//2-21)*4//3))
 return [one,two,paper('rossmoyne',9,p)]
